use axum::extract::State;
use axum_connect::{
    connect_core::Code,
    prelude::*,
    tower::{ConnectStream, ConnectStreamLayer},
};
use futures::{stream, Stream};
use std::sync::{
    atomic::{AtomicUsize, Ordering},
    Arc,
};
use tower_http::cors::CorsLayer;

pub mod hello {
    include!(concat!(env!("OUT_DIR"), "/hello.rs"));
    // Not actually generated, but required for the example to compile for now.
    // The real one will be generated by the build script.
    pub mod helloworldservice {
        pub fn routes<S: Clone + Send + Sync + 'static>(
            say_hello_handler: impl axum::handler::Handler<((axum::extract::State<S>, axum_connect::prelude::ConnectRequest<super::HelloRequest>),), S, axum::body::Body> + 'static,
            say_hello_stream_handler: impl axum::handler::Handler<((axum_connect::prelude::ConnectRequest<super::HelloRequest>),), S, axum::body::Body> + 'static,
        ) -> axum::Router<S> {
            axum::Router::new()
                .route(
                    "/hello.HelloWorldService/SayHello",
                    axum::routing::post(say_hello_handler),
                )
                .route(
                    "/hello.HelloWorldService/SayHelloStream",
                    axum::routing::post(say_hello_stream_handler),
                )
        }
    }
}
use hello::{helloworldservice, HelloRequest, HelloResponse};

#[derive(Clone, Default)]
struct AppState {
    counter: Arc<AtomicUsize>,
}

#[tokio::main]
async fn main() {
    let app = axum::Router::new()
        .merge(helloworldservice::routes(
            say_hello_unary,
            say_hello_stream,
        ))
        .fallback(unimplemented)
        .with_state(AppState::default())
        .layer(CorsLayer::very_permissive())
        .layer(ConnectStreamLayer);

    let listener = tokio::net::TcpListener::bind("127.0.0.1:3030")
        .await
        .unwrap();
    println!("listening on http://{:?}", listener.local_addr().unwrap());
    axum::serve(listener, app).await.unwrap();
}

async fn say_hello_unary(
    State(state): State<AppState>,
    ConnectRequest(req): ConnectRequest<HelloRequest>,
) -> Result<ConnectResponse<HelloResponse>, ConnectError> {
    let count = state.counter.fetch_add(1, Ordering::SeqCst);
    println!("Unary request #{}: {:?}", count, req);
    Ok(ConnectResponse(HelloResponse {
        message: format!("Hello, {}!", req.name),
    }))
}

async fn say_hello_stream(
    ConnectRequest(req): ConnectRequest<HelloRequest>,
) -> ConnectStream<impl Stream<Item = Result<HelloResponse, ConnectError>>> {
    let stream = stream::iter(vec![
        Ok(HelloResponse {
            message: format!("Hello, {}", req.name),
        }),
        Ok(HelloResponse {
            message: "Here is a second message.".to_string(),
        }),
        Err(ConnectError::new(Code::Unknown, "Stream error!".to_string())),
    ]);
    ConnectStream::new(stream)
}

async fn unimplemented() -> ConnectError {
    ConnectError::new(
        Code::Unimplemented,
        "The requested service has not been implemented.",
    )
}
